-- ==============================================================================
-- MEDICATIONS CLINICAL REFERENCE DATABASE (INDIA NLEM 2022 / CLINICAL FORMULARY)
-- 100 Essential Medicines with Contraindications, Interactions, and Warnings
-- ==============================================================================

create extension if not exists pgcrypto;

create table if not exists public.medications (
  id uuid primary key default gen_random_uuid(),
  medicine_id text unique not null,
  medicine_name text not null,
  generic_name text not null,
  therapeutic_class text,
  common_indications text,
  do_not_use_or_major_contraindications text,
  major_precautions text,
  common_or_important_adverse_effects text,
  important_interactions text,
  monitoring_or_safety_notes text,
  population_scope text,
  pregnancy_note text,
  pediatric_note text,
  renal_note text,
  hepatic_note text,
  self_medication_status text,
  evidence_basis text,
  source_required boolean default true,
  last_verified date,
  verification_status text not null default 'DRAFT—clinical validation required',
  notes text,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create index if not exists idx_medications_generic_name on public.medications(generic_name);
create index if not exists idx_medications_class on public.medications(therapeutic_class);
create index if not exists idx_medications_verification on public.medications(verification_status);

on conflict (medicine_id) do update set
medicine_name=excluded.medicine_name,
generic_name=excluded.generic_name,
therapeutic_class=excluded.therapeutic_class,
common_indications=excluded.common_indications,
do_not_use_or_major_contraindications=excluded.do_not_use_or_major_contraindications,
major_precautions=excluded.major_precautions,
common_or_important_adverse_effects=excluded.common_or_important_adverse_effects,
important_interactions=excluded.important_interactions,
monitoring_or_safety_notes=excluded.monitoring_or_safety_notes,
population_scope=excluded.population_scope,
pregnancy_note=excluded.pregnancy_note,
pediatric_note=excluded.pediatric_note,
renal_note=excluded.renal_note,
hepatic_note=excluded.hepatic_note,
self_medication_status=excluded.self_medication_status,
evidence_basis=excluded.evidence_basis,
source_required=excluded.source_required,
last_verified=excluded.last_verified,
verification_status=excluded.verification_status,
notes=excluded.notes;
